window.docContents[224].resolve({"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Substitution":{"contents":"The definition of substitution remains exactly the same as for the\npure STLC.\n\nsection\nset_option hygiene false in\nlocal macro_rules (kind := Stlc.tmBracket)\n  | `(<{ [$x := $s] $t }>) => do\n      `(subst $(← Stlc.varStr x) <{ $s:stlcTm }> <{ $t:stlcTm }>)\n\ndef subst (x : String) (s : Tm) (t : Tm) : Tm :=\n  match t with\n  -- pure STLC\n  | .var y =>\n      if x = y then s else t\n  | <{ λ ~y : ~τ . ~t₁}> =>\n      if x = y then t else <{ λ ~y : ~τ . [~x := ~s] ~t₁ }>\n  | <{ ~t₁ ~t₂ }> =>\n      <{ ([~x := ~s] ~t₁) ([~x := ~s] ~t₂) }>\n  -- unit\n  | .unit => <{ unit }>\n  -- bools\n  | <{ true }> => <{ true }>\n  | <{ false }> => <{ false }>\n  | <{ if ~t₁ then ~t₂ else ~t₃ }> =>\n      <{ if [~x := ~s] ~t₁ then [~x := ~s] ~t₂ else [~x := ~s] ~t₃ }>\n\n  -- Complete the following cases when you do the `products` exercise later\n  | <{(~t₁, ~t₂)}> =>\n      solution!(<{ ([~x := ~s] ~t₁ , [~x := ~s] ~t₂) }>)\n  | Tm.fst t =>\n      solution!(<{ fst ([~x := ~s] ~t)}>)\n  | Tm.snd t =>\n      solution!(<{ snd ([~x := ~s] ~t)}>)\n\nend\n\nmacro_rules (kind := Stlc.tmBracket)\n  | `(<{ [$x := $s] $t }>) => do\n      `(subst $(← Stlc.varStr x) <{ $s:stlcTm }> <{ $t:stlcTm }>)\n\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Formal Definitions","header":"8.2.2. Substitution","id":"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Substitution"}});